package main

import (
	"gno.land/r/gov/dao"
	valv3 "gno.land/r/sys/validators/v3"
)

func main(cur realm) {
	r := valv3.NewValidatorProposalRequest(
		cross(cur),
		[]valv3.ValoperChange{
			valv3.NewValoperChange(address("g1rw8av9eghy9h8vajktzk9d0wn2sd5d9ftwkhuf"), 0),
		},
		"Remove validator g1rw8av9eghy9h8vajktzk9d0wn2sd5d9ftwkhuf",
		"Remove operator g1rw8av9eghy9h8vajktzk9d0wn2sd5d9ftwkhuf from the active valset.",
	)
	pid := dao.MustCreateProposal(cross(cur), r)
	dao.MustVoteOnProposalSimple(cross(cur), int64(pid), "YES")
	dao.ExecuteProposal(cross(cur), pid)
}
